_VIEWS = {}

class _ModuleView(ModuleType):
    """Keep attribute reads and monkeypatches linked to the same implementation."""
    def __init__(self, name, target, names):
        super().__init__(name)
        self.__dict__.update(_target=target, _names=names)

    def __getattr__(self, name):
        return getattr(self._target, self._names.get(name, name))

    def __setattr__(self, name, value):
        names = self.__dict__.get('_names', {})
        if name in names:
            setattr(self._target, names[name], value)
        else:
            super().__setattr__(name, value)


def import_module(name, package=None):
    if name not in MODULES:
        return _import_module(name, package)
    if name not in _VIEWS:
        target, names = MODULES[name]
        view = _ModuleView(name, _import_module(target), names)
        _VIEWS[name] = view
        if target != name:
            sys.modules.setdefault(name, view)
    return _VIEWS[name]


def preserve_function(name, module):
    def decorate(fn):
        fn.__name__ = name
        fn.__qualname__ = name
        fn.__module__ = module
        return fn
    return decorate


def preserve_class(name, module):
    def decorate(cls):
        namespace = sys._getframe(1).f_globals
        cls.__name__ = name
        cls.__qualname__ = name
        cls.__module__ = module
        import_module(module)  # inspect.getfile and persisted type identities use this alias.
        for attr, value in vars(cls).items():
            if isinstance(value, (staticmethod, classmethod)):
                value = value.__func__
            if isinstance(value, FunctionType):
                value.__module__ = module
                value.__qualname__ = name + '.' + attr
        if hasattr(cls, 'model_rebuild'):
            cls.model_rebuild(force=True, _types_namespace=namespace)
        return cls
    return decorate
